package dustin.cex.domains.kyc;
import dustin.cex.domains.mail.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 점검은 실제 DB의 메타데이터만 읽으며 금융/메일 상태를 바꾸지 않는지 검증한다. */
class CustomerMailOperationsIntegrationTest extends CustomerMailTestSupport {
    @Autowired CustomerMailOperations operations;
    CustomerMailOperations.Item read(UUID id){return operations.ownJob(maker.user().getId(),maker.sid(),id);}
    UUID exhausted(){UUID id=queued();for(int n=0;n<5;n++){outbox.finish(outbox.claim(),"SMTP_UNKNOWN");jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_id=?",id);}return id;}
    @Test void exhaustedIsVisibleWithoutRecipientTokenOrLease() throws Exception {UUID id=exhausted();var state=outbox.state(id);assertEquals(CustomerMailOperations.Signal.EXHAUSTED,read(id).signal());String raw=json.writeValueAsString(operations.events(maker.user().getId(),maker.sid(),id,null));for(String secret:List.of(customer.getEmail(),outbox.open(id).token(),"lease","cipher","userId","reference"))assertFalse(raw.contains(secret));assertEquals(state,outbox.state(id));assertEquals(10,operations.events(maker.user().getId(),maker.sid(),id,null).items().size());}
    @Test void activeLeaseIsNotAnErrorButExpiredLeaseIs(){UUID id=queued();var lease=outbox.claim();assertNull(read(id).signal());jdbc.update("UPDATE customer_mail_delivery SET lease_until=clock_timestamp()-interval '1 second' WHERE job_id=?",id);assertEquals(CustomerMailOperations.Signal.LEASE_EXPIRED,read(id).signal());assertEquals("SENDING",outbox.state(id).status());}
    @Test void overdueRetrySignalsDelayWithoutStealingLease(){UUID id=queued();outbox.finish(outbox.claim(),"SMTP_UNKNOWN");jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '6 minutes' WHERE job_id=?",id);assertEquals(CustomerMailOperations.Signal.DELAYED,read(id).signal());assertEquals("RETRY",outbox.state(id).status());}
    @Test void acceptedAndSuppressedAreNotAttention(){for(String result:List.of("SMTP_ACCEPTED","SUPPRESSED")){UUID id=queued();outbox.finish(outbox.claim(),result);assertNull(read(id).signal());}}
    @Test void emptyFilteredPagesStillAdvance(){var last=jdbc.queryForList("SELECT id,created_at FROM customer_mail_jobs ORDER BY created_at DESC,id DESC LIMIT 1");var after=last.isEmpty()?null:new CustomerMailOperations.Cursor(((java.sql.Timestamp)last.getFirst().get("created_at")).toInstant(),(UUID)last.getFirst().get("id"));for(int n=0;n<26;n++)queued();var p=operations.attention(maker.user().getId(),maker.sid(),after);assertEquals(25,p.scanned());assertTrue(p.items().isEmpty());assertNotNull(p.next());var next=operations.attention(maker.user().getId(),maker.sid(),p.next());assertEquals(1,next.scanned());assertNull(next.next());}
    @Test void absentMalformedAndFuturePositionsAreRejected(){assertEquals(404,assertThrows(ResponseStatusException.class,()->read(UUID.randomUUID())).getStatusCode().value());for(var c:List.of(new CustomerMailOperations.Cursor(null,UUID.randomUUID()),new CustomerMailOperations.Cursor(Instant.now(),null),new CustomerMailOperations.Cursor(Instant.now().plusSeconds(600),UUID.randomUUID())))assertEquals(400,assertThrows(ResponseStatusException.class,()->operations.attention(maker.user().getId(),maker.sid(),c)).getStatusCode().value());}
    @Test void customerAndForeignSessionCannotInspect(){UUID id=queued();assertThrows(ResponseStatusException.class,()->operations.ownJob(customer.getId(),sid,id));assertThrows(ResponseStatusException.class,()->operations.ownJob(maker.user().getId(),checker.sid(),id));}
    @Test void disabledOrStaleStaffIsRejected(){UUID id=queued();var token=tokens.findBySessionId(maker.sid()).orElseThrow();token.setMfaVerifiedAt(LocalDateTime.now().minusMinutes(6));tokens.saveAndFlush(token);assertThrows(ResponseStatusException.class,()->read(id));var u=users.findById(checker.user().getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->operations.ownJob(checker.user().getId(),checker.sid(),id));}
    @Test void auditFailurePreventsMetadataResponse(){UUID id=queued();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_MAIL_INSPECTED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->read(id));reset(audit);assertNotNull(read(id));}
    @Test void httpReadIsAuthenticatedAndDoesNotExposeSecrets() throws Exception {UUID id=exhausted();String raw=mvc.perform(get("/api/admin/operations/customer-mail/"+id).header("Authorization","Bearer "+maker.access())).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andReturn().getResponse().getContentAsString();assertFalse(raw.contains(customer.getEmail()));assertFalse(raw.contains(outbox.open(id).token()));mvc.perform(get("/api/admin/operations/customer-mail/"+id).header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());mvc.perform(get("/api/admin/operations/customer-mail")).andExpect(status().isUnauthorized());}
    @Test void expiredMetadataIsVisibleWithoutDecryptingPayload(){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO customer_mail_jobs(id,user_id,kind,reference_id,content_mac,key_id,expires_at) VALUES(?,?,?,?,?,?,clock_timestamp()-interval '1 second')",id,customer.getId(),"EMAIL_VERIFICATION",UUID.randomUUID(),"0".repeat(64),"0".repeat(64));jdbc.update("INSERT INTO customer_mail_delivery(job_id,status) VALUES(?,'PENDING')",id);assertEquals(CustomerMailOperations.Signal.EXPIRED,read(id).signal());}
    @Test void auditorCanReadButNotDispatch() throws Exception {var auditor=account(dustin.cex.domains.auth.model.entity.UserRole.AUDITOR);UUID id=queued();assertNotNull(operations.ownJob(auditor.user().getId(),auditor.sid(),id));mvc.perform(post("/api/admin/operations/customer-mail/"+id).header("Authorization","Bearer "+auditor.access())).andExpect(status().isForbidden());assertEquals("PENDING",outbox.state(id).status());}

}
